package com.supportsphere.controller; import com.supportsphere.model.*; import com.supportsphere.dao.*; import com.supportsphere.service.*; import com.supportsphere.util.*; import javafx.fxml.*; import javafx.collections.*; import javafx.scene.control.*; import java.util.*;
public class VolunteerDashboardController { @FXML Label welcome,rating,verification,skills,available,assignedCount,activeCount,notificationCount; @FXML TableView<AssistanceRequest> table; @FXML TableColumn<AssistanceRequest,String> idCol,taskCol,locationCol,urgencyCol,dateCol,matchCol; private final RequestService requests=new RequestService(); private final VolunteerDAO volunteers=new VolunteerDAO(); private final MatchingService matching=new MatchingService(); private final AssignmentService assignments=new AssignmentService(); @FXML void initialize(){load();} private void load(){try{Volunteer v=volunteers.findById(Session.getUser().getUserId()).orElseThrow(()->new IllegalStateException("Your volunteer profile is missing. Please recreate the account using the SupportSphere registration flow."));welcome.setText("Good day, "+v.getName().split(" ")[0]+" 👋");rating.setText(String.format("%.1f ★ (%d)",v.getRating(),v.getRatingCount()));verification.setText(v.getVerificationStatus());skills.setText(String.join(" · ",v.getSkills()));available.setText(v.getAvailabilityStart()+" – "+v.getAvailabilityEnd());List<AssistanceRequest>src=requests.open();List<AssistanceRequest>shown=new ArrayList<>();for(AssistanceRequest r:src){List<MatchingService.VolunteerMatch>m=matching.rank(r,List.of(v));if(!m.isEmpty())shown.add(r);}table.setItems(FXCollections.observableArrayList(shown));idCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty("#"+c.getValue().getRequestId()));taskCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getTaskType()));locationCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getLocationLabel()));urgencyCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getUrgency().name()));dateCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getPreferredDate()+" · "+c.getValue().getStartTime()));matchCol.setCellValueFactory(c->{try{var m=matching.rank(c.getValue(),List.of(v));return new javafx.beans.property.SimpleStringProperty(m.isEmpty()?"—":m.getFirst().score()+"% match");}catch(Exception e){return new javafx.beans.property.SimpleStringProperty("—");}});List<Map<String,Object>>mine=assignments.mine(v.getUserId());assignedCount.setText(""+mine.size());activeCount.setText(""+mine.stream().filter(x->List.of("ASSIGNED","IN_PROGRESS").contains(String.valueOf(x.get("status")))).count());notificationCount.setText(""+new NotificationDAO().count(v.getUserId()));}catch(Exception e){Dialogs.error("Dashboard error",e.getMessage());}} @FXML void accept(){AssistanceRequest r=table.getSelectionModel().getSelectedItem();if(r==null){Dialogs.info("Select a task","Choose a recommended request first.");return;}try{assignments.accept(r.getRequestId(),Session.getUser().getUserId());Dialogs.info("Request accepted","You are now assigned to request #"+r.getRequestId()+".");load();}catch(Exception e){Dialogs.error("Could not accept request",e.getMessage());load();}} @FXML void start(){change("start");} @FXML void complete(){change("complete");} private void change(String action){try{List<Map<String,Object>>m=assignments.mine(Session.getUser().getUserId());if(m.isEmpty()){Dialogs.info("No assignments","You don't have any assignments yet.");return;}Map<String,Object>selected=m.stream().filter(x->String.valueOf(x.get("status")).equals(action.equals("start")?"ASSIGNED":"IN_PROGRESS")).findFirst().orElse(null);if(selected==null){Dialogs.info("No matching assignment",action.equals("start")?"No assigned task is waiting to be started.":"No in-progress task is ready to be completed.");return;}int id=((Number)selected.get("request_id")).intValue();if(action.equals("start"))assignments.start(id,Session.getUser().getUserId());else assignments.complete(id,Session.getUser().getUserId());Dialogs.info("Updated","Request #"+id+" is now "+(action.equals("start")?"IN PROGRESS":"COMPLETED")+".");load();}catch(Exception e){Dialogs.error("Could not update assignment",e.getMessage());}} @FXML void viewMyTasks(){try{List<Map<String,Object>>m=assignments.mine(Session.getUser().getUserId());StringBuilder b=new StringBuilder();for(Map<String,Object>x:m)b.append("#").append(x.get("request_id")).append(" · ").append(x.get("task_type")).append(" · ").append(x.get("status")).append("\n");Dialogs.info("My task history",b.length()==0?"No assignments yet.":b.toString());}catch(Exception e){Dialogs.error("Could not load history",e.getMessage());}} @FXML void notifications(){try{NotificationDAO n=new NotificationDAO();List<String>x=n.unread(Session.getUser().getUserId());Dialogs.info("Notifications",x.isEmpty()?"You're all caught up.":String.join("\n\n",x));n.markRead(Session.getUser().getUserId());load();}catch(Exception e){Dialogs.error("Notifications error",e.getMessage());}} @FXML void logout(){Session.clear();try{SceneManager.show("login.fxml","SupportSphere — Sign in");}catch(Exception e){}} }
